/// <summary>
/// Finds a record
/// </summary>
/// <param name = "_quotationId">Quotation id</param>
/// <param name = "_forupdate">false or truefor update</param>
/// <returns>KCS_KBVSalesTenderLink record</returns>
public static KCS_KBVSalesTenderLink find(QuotationIdBase _quotationId, boolean _forupdate = false)
{
    KCS_KBVSalesTenderLink     KCS_KBVSalesTenderLink;
    ;

    if (_quotationId)
    {
        KCS_KBVSalesTenderLink.selectForUpdate(_forupdate);
        KCS_KBVSalesTenderLink.selectLocked(_forupdate);

        select firstonly KCS_KBVSalesTenderLink
        where KCS_KBVSalesTenderLink.QuotationId == _quotationId;
    }

    return KCS_KBVSalesTenderLink;
}

/// <summary>
/// Calculates new KCS_QLLPosition
/// </summary>
/// <param name = "newLVPosition">LV postion</param>
void KCS_KBVTenderMatrixModified(str newLVPosition)
{
    SalesQuotationLine      quotLine;
    KCS_KBVSalesTenderLink  salesTenderLink;
    ;

    salesTenderLink = KCS_KBVSalesTenderLink::find(this.QuotationId);

    ttsbegin;
    while select forupdate quotLine where quotLine.QuotationId == this.QuotationId
                                   && quotLine.RecId
    {
        quotLine.KCS_QLLVPosition   = KCS_KBVTenderIdUtility::fillMatrix(quotLine.KCS_QLLVPosition, salesTenderLink.TenderMatrix);
        quotLine.doUpdate();
    }
    ttscommit;
}

/// <summary>
/// Checks if record exists
/// </summary>
/// <param name = "_quotationId">Quotation id</param>
/// <returns>true or false</returns>
static boolean exist(QuotationIdBase _quotationId)
{
    if (!_quotationId)
    {
        return false;
    }

    return (select firstonly RecId from KCS_KBVSalesTenderLink
                where KCS_KBVSalesTenderLink.QuotationId == _quotationId).RecId != 0;
}
